import numpy as np
import xarray as xr
from satpy.resample.native import NativeResampler

class MockArea:
    def __init__(self, shape):
        self.shape = shape

def test_native_resample_mismatch():
    # Mock data: shape (5560, 100)
    data_val = np.random.rand(5560, 100)
    data = xr.DataArray(data_val, dims=('y', 'x'), name='test')

    # Mock target area: shape (5568, 100)
    target_area = MockArea((5568, 100))

    resampler = NativeResampler()
    resampler.target_geo_def = target_area

    try:
        res = resampler.compute(data)
        print("Resample succeeded unexpectedly")
    except ValueError as e:
        print(f"Caught expected ValueError: {e}")
    except Exception as e:
        print(f"Caught unexpected exception: {type(e).__name__}: {e}")

if __name__ == "__main__":
    test_native_resample_mismatch()

